    public int hashCode() {
        return toTree().printTree().hashCode();
    }
}

class BinaryTree {
    private final Zipper root;

    BinaryTree(int value) {
        this(new Zipper(value));
    }

    BinaryTree(Zipper root) {
        this.root = root;
    }

    Zipper getRoot() {
        return root;
    }

    String printTree() {
        return print(root);
    }

    private static String print(Zipper zipper) {
        return "value: " + zipper.value
                + ", left: " + printChild(zipper.left)
                + ", right: " + printChild(zipper.right);
    }

    private static String printChild(Zipper zipper) {
        return zipper == null ? "null" : "{ " + print(zipper) + " }";
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof BinaryTree)) {
            return false;
        }
        return printTree().equals(((BinaryTree) other).printTree());
    }

    @Override
    public int hashCode() {
        return printTree().hashCode();
    }
}
